import csv
import io
import re


def parse_csv(raw_csv: str):
    expected_width = 8
    numeric_fields = (0, 1, 5, 6, 7)
    number = re.compile(r"[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?")

    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    records = list(csv.reader(io.StringIO(raw_csv, newline=""),
                              delimiter=",", quotechar='"', doublequote=True))

    def looks_like_data(row):
        return len(row) >= expected_width and all(
            number.fullmatch(row[index].strip()) is not None
            for index in numeric_fields
        )

    def looks_like_header(row):
        return len(row) == expected_width and all(
            any(char.isalpha() for char in row[index])
            and number.fullmatch(row[index].strip()) is None
            for index in numeric_fields
        )

    # The sample begins with data despite the one-header hint.
    first = next((index for index, row in enumerate(records) if row), None)
    columns = []
    if first is not None and looks_like_header(records[first]):
        following = next((row for row in records[first + 1:] if row), None)
        if following is None or looks_like_data(following):
            columns = records.pop(first)

    width = max(expected_width, max((len(row) for row in records), default=0))
    used_names = set(columns)
    for position in range(len(columns) + 1, width + 1):
        name = f"column_{position}"
        while name in used_names:
            name += "_"
        columns.append(name)
        used_names.add(name)

    return {
        "columns": columns,
        "rows": [row + [""] * (width - len(row)) for row in records],
    }
